mapper.select:
select * from yh_user_commodity_data as dit where inventory > 0
and grouping_id = #{groupingId,jdbcType=INTEGER}
and putaway = 1
and dit.pzk_integral <= (select healthlevelstars from yh_user_step where user_code = #{userCode})
and standby = 1 order by add_date desc limit #{page},#{pageSize}
